use alloc::vec;
use alloc::vec::Vec;

use harness::{Event, Observable};
use process::{Answer, Caller, Giving, Processable, Unremembered};

impl Observable for Hook {
    fn events(&self) -> Vec<Event> {
        match self {
            // A resume is Resumed, followed by its context's size; a compaction gives no event from the hook.
            Hook::SessionStart(start) => match &start.source {
                Source::Startup => vec![Event::Started],
                Source::Resume(tokens) => core::iter::once(Event::Resumed).chain(tokens.iter().copied().map(Event::ContextSize)).collect(),
                Source::Compact => vec![],
            },
            Hook::UserPromptSubmit(prompt) => vec![Event::PromptSubmitted(prompt.clone())],
            Hook::PermissionRequest => vec![Event::PermissionAsked],
            Hook::PostToolUse => vec![Event::ToolUsed],
            Hook::Stop(stop) => {
                let mut events: Vec<Event> = stop.response_option.iter().cloned().map(Event::Responded).collect();
                events.push(Event::InFlight(stop.background_work_vector.clone()));
                events.push(Event::TurnEnded);
                events
            }
            Hook::SessionEnd(reason) => vec![Event::Ended(reason.clone())],
        }
    }
}

impl Observable for Row {
    fn events(&self) -> Vec<Event> {
        match self {
            Row::Assistant(tokens) => vec![Event::ContextSize(*tokens)],
            Row::TurnStarted(prompt) => vec![Event::PromptSubmitted(prompt.clone())],
            Row::TurnEnded => vec![Event::TurnEnded],
            Row::Interrupted => vec![Event::Interrupted],
            Row::Compacted(boundary) => {
                let mut events = vec![Event::Compacted(boundary.compaction.clone())];
                events.extend(boundary.tokens_option.map(Event::ContextSize));
                events
            }
            Row::Other => vec![],
        }
    }
}

impl Processable for ReportProcess {
    type Taken = ReportTaken;
    type Gift = Gift;
    type Outcome = Reporting;

    fn begin<N: Giving<Self>>(&mut self, mut manager: N) -> Option<Reporting> {
        manager.give(Reported {});
        if let Hook::SessionStart(start) = &self.hook {
            // A session that started is read from its first row; one resumed or compacted from the file's end.
            let read_from = match start.source {
                Source::Startup => ReadFrom::Offset(Offset(0)),
                Source::Resume(_) | Source::Compact => ReadFrom::FileEnd,
            };
            manager.give(Watch { session_id: self.session_id.clone(), file_path: start.file_path.clone(), read_from });
        }
        manager.give(Observe { session_id: self.session_id.clone(), event_vector: self.hook.events(), offset_option: None });
        None
    }

    fn take<N: Giving<Self>>(&mut self, taken: ReportTaken, mut manager: N) -> Option<Reporting> {
        match taken {
            ReportTaken::Answer(Answer::Succeeded) => None,
            ReportTaken::Answer(Answer::Failed) => Some(Reporting::Unremembered),
            ReportTaken::Observation(Err(Unremembered {})) => Some(Reporting::Unremembered),
            ReportTaken::Observation(Ok(observation)) => {
                for changed in observation.0 {
                    manager.give(changed)
                }
                Some(Reporting::Observed)
            }
        }
    }
}

impl Processable for WatchProcess {
    type Taken = WatchTaken;
    type Gift = Gift;
    type Outcome = Watching;

    fn begin<N: Giving<Self>>(&mut self, mut manager: N) -> Option<Watching> {
        manager.give(Follow_Data { file_path: self.file_path.clone(), read_from: self.read_from.clone(), row_count: self.row_count });
        None
    }

    fn take<N: Giving<Self>>(&mut self, taken: WatchTaken, mut manager: N) -> Option<Watching> {
        match taken {
            WatchTaken::Following(Ok(following)) => {
                self.read_from = ReadFrom::Offset(following.offset);
                let event_vector = following.row_vector.iter().flat_map(Observable::events).collect();
                manager.give(Observe { session_id: self.session_id.clone(), event_vector, offset_option: Some(following.offset) });
                None
            }
            WatchTaken::Following(Err(_)) => Some(Watching::Unfollowed),
            // A Watch goes on when an Observe was not kept: its next carries the later offset.
            WatchTaken::Observation(Err(Unremembered {})) => None,
            WatchTaken::Observation(Ok(observation)) => {
                for changed in observation.0 {
                    manager.give(changed)
                }
                None
            }
        }
    }
}

impl Processable for SubscribeProcess {
    type Taken = SubscribeTaken;
    type Gift = Gift;
    /// It ends one way, when its connection closes, and so declares no outcome.
    type Outcome = ();

    fn begin<N: Giving<Self>>(&mut self, mut manager: N) -> Option<()> {
        manager.give(Recall {});
        None
    }

    /// It answers with every session as it is now, then rests while its connection is open.
    fn take<N: Giving<Self>>(&mut self, recollection: SubscribeTaken, mut manager: N) -> Option<()> {
        if let Ok(recollection) = recollection {
            manager.give(Subscribed(recollection.0));
        }
        None
    }
}

impl Processable for ConfigureProcess {
    type Taken = ConfigureTaken;
    type Gift = Gift;
    type Outcome = Configuring;

    fn begin<N: Giving<Self>>(&mut self, mut manager: N) -> Option<Configuring> {
        manager.give(Keep(self.set.clone()));
        None
    }

    fn take<N: Giving<Self>>(&mut self, answer: ConfigureTaken, mut manager: N) -> Option<Configuring> {
        match answer {
            Answer::Succeeded => {
                manager.give(Configured(self.set.clone()));
                Some(Configuring::Configured)
            }
            Answer::Failed => Some(Configuring::Unremembered),
        }
    }
}

/// Born of a Prepare, holding the hook client and the hooks as configured then:
/// it gives Install, and answers with the path the translator wrote, or None,
/// the reason for it being its outcome in the trace.
impl Processable for PrepareProcess {
    type Taken = PrepareTaken;
    type Gift = Gift;
    type Outcome = Preparing;

    fn begin<N: Giving<Self>>(&mut self, mut manager: N) -> Option<Preparing> {
        match &self.hook_client_option {
            Some(hook_client) => {
                manager.give(Install_Data { hook_client: hook_client.clone(), hooks: self.hooks.clone() });
                None
            }
            None => {
                manager.give(Prepared(None));
                Some(Preparing::Unconfigured)
            }
        }
    }

    fn take<N: Giving<Self>>(&mut self, installation: PrepareTaken, mut manager: N) -> Option<Preparing> {
        let (prepared, preparing) = match installation {
            Ok(Installation_Data::Installed(file_path)) => (Some(file_path), Preparing::Installed),
            Ok(Installation_Data::Uninstalled(_)) => (None, Preparing::Uninstalled),
            Err(_) => (None, Preparing::Unobserved),
        };
        manager.give(Prepared(prepared));
        Some(preparing)
    }
}
